-- The FAA registry of all 314K US civil aircraft -- N-number, owner name and address, make/model, registration dates.
-- Auto-generated by scripts/gen_evidence_pages.py: 314,417 rows > 100k, so this is a BOUNDED pre-aggregate (parquet-safe by construction), not select *.
select year("LAST_ACTION_DATE") as year, count(*) as records
from THE_LIBRARY.TRANSPORT.AIRCRAFT_REGISTRY
where "LAST_ACTION_DATE" is not null
group by 1
order by 1
